#include "../../models/film_three_finger/SharedFilmSystem.h"
#include <iostream>
#include <iomanip>
using namespace regrip_three_finger;
int main(int argc,char**argv){try{
 if(argc!=5)throw std::invalid_argument("mass,state,steps,output required");unsigned steps=std::stoul(argv[3]);if(steps!=7&&steps!=8&&steps!=14&&steps!=16&&steps!=28&&steps!=32)throw std::invalid_argument("profiled7/14/28 or8/16/32 post-impact steps only");SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned nf=s.shared.nf,n=s.shared.M.rows();std::ifstream mass(argv[1]);unsigned count;mass>>count;if(count!=s.shared.films[0].film.mass.size())throw std::runtime_error("post-impact mass dimension");s.shared.M.setZero();
 for(unsigned f=0;f<3;++f){auto&film=s.shared.films[f].film;for(unsigned i=0;i<count;++i){double m;mass>>m;if(!(m>0)||std::abs(m-film.mass[i])>1e-13*film.mass[i])throw std::runtime_error("post-impact mass differs");film.mass[i]=m;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;int k=film.index[a];if(k>=0)s.shared.M(f*nf+k,f*nf+k)+=m*film.weight[a]*film.weight[a];}}}double m,I;mass>>m>>I;if(!mass||m!=.0001||std::abs(I-.036)>1e-16)throw std::runtime_error("post-impact rigid mass differs");s.shared.M.bottomRightCorner<6,6>().diagonal().head<3>().setConstant(m);s.shared.M.bottomRightCorner<6,6>().diagonal().tail<3>().setConstant(I);
 std::ifstream initial(argv[2]);unsigned size;initial>>size;Eigen::VectorXd q(n),v(n);for(double&x:q)initial>>x;for(double&x:v)initial>>x;if(!initial||size!=n||!q.allFinite()||!v.allFinite())throw std::runtime_error("finite saved actual post-impact state required");if(std::ifstream(argv[4]))throw std::runtime_error("post-impact output exists");std::ofstream out(argv[4]);out<<std::setprecision(17)<<"time,gap,momentum,normal_velocity,force,q,v\n";double h=.0014/steps;EventControl control{.0001,.01,.02,.03,true};
 for(unsigned step=0;step<steps;++step){double time=.0002+step*h;auto r=regrip_collocation::persistentRows(s.shared.M,2,q,v,time,h,[&](const auto&x,double t){return s.force(x,control.sample(t).tension);},[&](const auto&x){return s.geometry(x);});double gap=s.clearance(r.q);for(const auto&stage:r.stages)gap=std::min(gap,s.clearance(stage.q));if(gap< -1e-10)throw std::runtime_error("post-impact whole-stage clearance failed");q=r.q;v=r.v;out<<time+h<<','<<gap<<','<<r.momentumResidual<<','<<r.velocityResidual;for(const auto*value:{&r.stages[1].force,&q,&v}){out<<',';for(int i=0;i<value->size();++i)out<<(i?" ":"")<<(*value)(i);}out<<'\n';out.flush();}
 std::cout<<"PASS independent saved-actual-state post-impact refinement;NOT actual SOFA/full event time/grasp\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
